referenceSolutions.javascript:
export function wordLadder(begin        , end        , words          )         {
if(begin===end)return 1;const remaining=new Set(words);if(!remaining.has(end))return 0;remaining.delete(begin);let q=[begin],length=1;while(q.length){const next         =[];for(const w of q)for(let i=0;i<w.length;i++)for(let c=97;c<=122;c++){const v=w.slice(0,i)+String.fromCharCode(c)+w.slice(i+1);if(!remaining.has(v))continue;if(v===end)return length+1;remaining.delete(v);next.push(v);}q=next;length++;}return 0;
}

